<script setup lang="ts">
const props=defineProps<{location?:{latitude:number;longitude:number};name:string;url:string}>();const el=ref<HTMLElement|null>(null);const open=ref(false);const error=ref('');const config=useRuntimeConfig()
async function show(){open.value=true;await nextTick();if(!config.public.googleMapsApiKey||!props.location){error.value='Googleマップで場所をご確認ください。';return}try{const win=window as any;if(!win.google?.maps){await new Promise<void>((resolve,reject)=>{const script=document.createElement('script');script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(config.public.googleMapsApiKey)}&v=weekly&loading=async&callback=hitokuchiMapsReady`;win.hitokuchiMapsReady=resolve;script.onerror=reject;document.head.appendChild(script)})}const position={lat:props.location.latitude,lng:props.location.longitude};const map=new win.google.maps.Map(el.value,{center:position,zoom:16,disableDefaultUI:true,zoomControl:true});new win.google.maps.Marker({map,position,title:props.name})}catch{error.value='地図を読み込めませんでした。Googleマップでご確認ください。'}}
</script>
<template><div class="map-panel"><button v-if="!open" class="button secondary" @click="show">地図を表示する</button><div v-show="open&&!error" ref="el" class="google-map"/><p v-if="error">{{error}} <a :href="url" target="_blank" rel="noopener noreferrer">Googleマップで見る ↗</a></p></div></template>
